const TRIAGE_SCHEMA = {
  type: 'object',
  properties: {
    candidates: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          type: { type: 'string', enum: ['decision', 'pattern', 'troubleshooting'] },
          title: { type: 'string' },
          quote: { type: 'string' },
          approxDate: { type: 'string' },
          matchesKnown: {
            type: 'string',
            enum: ['sqlite_markdown', 'memory_lifecycle', 'ingestion_decomposition', 'skill_resolution', 'qmd_search', 'git_native', 'none'],
          },
          confidence: { type: 'string', enum: ['high', 'low'] },
        },
        required: ['type', 'title', 'quote', 'matchesKnown', 'confidence'],
      },
    },
  },
  required: ['candidates'],
}

const MERGE_SCHEMA = {
  type: 'object',
  properties: {
    items: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          type: { type: 'string', enum: ['decision', 'pattern', 'troubleshooting'] },
          title: { type: 'string' },
          evidence: { type: 'array', items: { type: 'string' } },
          sessionFiles: { type: 'array', items: { type: 'string' } },
          confidence: { type: 'string', enum: ['high', 'low'] },
        },
        required: ['type', 'title', 'evidence', 'confidence'],
      },
    },
  },
  required: ['items'],
}

const DRAFT_SCHEMA = {
  type: 'object',
  properties: {
    kind: { type: 'string', enum: ['adr', 'development', 'troubleshooting', 'skip'] },
    slug: { type: 'string' },
    content: { type: 'string' },
    citations: { type: 'array', items: { type: 'string' } },
  },
  required: ['kind', 'slug', 'content', 'citations'],
}

const VERIFY_SCHEMA = {
  type: 'object',
  properties: {
    approved: { type: 'boolean' },
    issues: { type: 'array', items: { type: 'string' } },
  },
  required: ['approved', 'issues'],
}

phase('Triage transcripts')
const triageResults = await pipeline(
  TRANSCRIPTS,
  (file) =>
    agent(
      `You are triaging ONE Claude Code session transcript (JSONL, one JSON object per line) for the wakil repo, looking for two things: (1) architectural DECISIONS ("we chose X over Y", "instead of doing A we did B", rejecting an approach), and (2) troubleshooting/PATTERN moments (a real bug found and fixed, especially involving root-cause explanation; or a dev convention/pattern being established or reused deliberately).

Transcript file: ${file}

Do NOT read the whole file (it may be multiple MB). Instead use Bash/grep against it:
- grep -noiE for phrases like: "instead of", "rather than", "we (chose|decided|went with|opted)", "reject", "deprecat", "workaround", "root cause", "the (bug|issue) was", "stranded", "gotcha", "fixed by", "turns out", "pattern", "convention", "always (do|use)", "should (always|never)"
- grep -n '"file_path":"[^"]*docs/' to find moments where docs/*.md files were edited (often coincide with decisions)
- Pull a bit of surrounding context for real hits (grep -A2 -B2, or by line number) — JSONL lines contain a "message" object with "content" (string or array with "text"/"thinking"/"tool_use" blocks) and a "timestamp" field.

Filter out casual/irrelevant matches. For each genuine candidate, classify it:
- type: "decision" (an architectural choice), "pattern" (a recurring dev convention worth generalizing), or "troubleshooting" (a real bug/gotcha with a fix)
- matchesKnown: does this correspond to one of these six already-known decisions, or none?
  - sqlite_markdown: Markdown as source of truth, SQLite as operational store
  - memory_lifecycle: reviewable-diff memory lifecycle, no autonomous background rewriting
  - ingestion_decomposition: ingestion decomposed into classify/extract/resolve/enforce/finalize without a multi-agent mechanism
  - skill_resolution: skill resolution precedence, first-match-wins, no merging
  - qmd_search: QMD as first-class search over SQLite FTS5
  - git_native: git-native change tracking (branches/PRs for ingest)
  - none: doesn't match any of the above
- quote: a short, EXACT excerpt (under 300 chars) copied verbatim from the transcript, not paraphrased
- approxDate: from the nearby "timestamp" field if visible, else omit
- confidence: "high" only if the quote clearly and unambiguously supports the classification; "low" otherwise

Return only genuine candidates (it is completely fine and expected to return an empty array if this session has nothing relevant — most sessions probably won't).`,
      { schema: TRIAGE_SCHEMA, phase: 'Triage transcripts', label: `triage:${file.split('/').pop()}` }
    )
)

const allCandidates = triageResults
  .filter(Boolean)
  .flatMap((r, i) => (r.candidates || []).map((c) => ({ ...c, sessionFile: TRANSCRIPTS[i] })))
log(`Triage surfaced ${allCandidates.length} candidates across ${TRANSCRIPTS.length} sessions`)

const corroboration = {}
KNOWN_DECISIONS.forEach((d) => (corroboration[d.key] = []))
const novel = []
allCandidates.forEach((c) => {
  if (c.matchesKnown && c.matchesKnown !== 'none' && corroboration[c.matchesKnown]) {
    corroboration[c.matchesKnown].push(c)
  } else if (c.confidence === 'high') {
    novel.push(c)
  }
})
log(`${novel.length} novel high-confidence candidates outside the 6 known decisions`)

phase('Cluster novel candidates')
let clustered = { items: [] }
if (novel.length) {
  clustered = await agent(
    `Here are ${novel.length} raw candidate notes extracted independently from different session transcripts for the wakil repo. Cluster them into a small number of DISTINCT dev patterns / troubleshooting incidents / possible new architectural decisions. Merge duplicates (the same incident or pattern often gets mentioned across multiple sessions — combine their evidence into one item). Drop anything trivial, vague, or not clearly evidenced by its quote. Be conservative: it is better to drop a weak candidate than to inflate the count.

Raw candidates:
${JSON.stringify(novel, null, 2)}

For each surviving cluster, return type, a clear title, the merged evidence array (keep the original exact quotes), the sessionFiles they came from, and confidence.`,
    { schema: MERGE_SCHEMA, phase: 'Cluster novel candidates' }
  )
}
log(`Clustered into ${(clustered.items || []).length} distinct novel items`)

phase('Draft')
const knownDrafts = await parallel(
  KNOWN_DECISIONS.map((d) => () =>
    agent(
      `Draft an Architecture Decision Record for wakil's decision: "${d.title}".

Primary pointer: ${d.pointer}

Corroborating transcript quotes found during triage (may be empty): ${JSON.stringify(corroboration[d.key])}

IMPORTANT: independently verify the primary source yourself — Read the doc file directly, and use \`gh pr list --state merged\`, \`gh pr view <n>\`, or \`git log\`/\`git show\` to locate and read the actual merged PR if relevant. Do not rely solely on this prompt's paraphrase; quote what you actually find.

Write the ADR as markdown with this exact frontmatter shape (matching this repo's existing docs/ convention):
---
title: <short decision title>
status: accepted
date: <YYYY-MM-DD, your best evidence-based estimate, e.g. from PR merge date or commit date>
audience: wakil design
---
Followed by "## Context", "## Decision", "## Consequences", and "## Sources" (list exact citations: doc file + section, PR number with title, commit SHA, or transcript file + quoted excerpt).

If comparative rationale (why this over an alternative) genuinely isn't found anywhere you checked, say so plainly in Consequences rather than inventing it — integrity over completeness.

Return kind: "adr", slug: a kebab-case filename slug (no directory, no number, no .md extension), content: the full markdown, citations: an array of the exact citation strings you used.`,
      { schema: DRAFT_SCHEMA, phase: 'Draft', label: `draft:${d.key}` }
    )
  )
)

const novelDrafts = await parallel(
  (clustered.items || []).map((item) => () =>
    agent(
      `Draft a ${item.type === 'decision' ? 'new Architecture Decision Record' : item.type === 'pattern' ? 'docs/DEVELOPMENT.md entry' : 'docs/TROUBLESHOOTING.md entry'} for wakil based on this candidate surfaced from historical session transcripts: "${item.title}".

Evidence (exact quotes from transcripts): ${JSON.stringify(item.evidence)}
Session file(s): ${JSON.stringify(item.sessionFiles || [])}

Before writing, sanity-check the evidence is actually strong enough:
- decision: a real, deliberate architectural choice — not routine implementation work
- pattern (docs/DEVELOPMENT.md): a convention that should generalize to future, different work — not a one-off fix
- troubleshooting (docs/TROUBLESHOOTING.md): a bug/gotcha that cost real debugging time, wasn't obvious from the code, and would plausibly recur

If it doesn't clearly clear that bar, return kind: "skip", slug: "", content: "", citations: [].

Otherwise:
- For "decision": return kind "adr" with the same frontmatter/section shape as other ADRs in this repo (title/status/date/audience frontmatter, then Context/Decision/Consequences/Sources).
- For "pattern": return kind "development" with content being ONLY the entry snippet (not a whole file): "### <pattern name>\\n**Established:** YYYY-MM-DD · **Source:** <pointer>\\n\\n<2-5 sentences>"
- For "troubleshooting": return kind "troubleshooting" with content being ONLY the entry snippet: "### <short title>\\n**Date:** YYYY-MM-DD · **Source:** <pointer>\\n\\n<2-5 sentences: symptom, root cause, fix>"

Use only the evidence given — do not invent detail beyond what the quotes support. slug applies only to kind "adr" (kebab-case, no directory/number/extension); leave it "" otherwise. citations must be the exact quotes/pointers you relied on.`,
      { schema: DRAFT_SCHEMA, phase: 'Draft', label: `draft:novel:${item.title.slice(0, 40)}` }
    )
  )
)

const allDrafts = [...knownDrafts, ...novelDrafts].filter(Boolean).filter((d) => d.kind !== 'skip' && d.content)
log(`${allDrafts.length} drafts produced (excluding skips)`)

phase('Verify')
const verified = await parallel(
  allDrafts.map((d) => () =>
    agent(
      `Adversarially verify this drafted content for wakil's dev-docs backfill against ONLY its cited sources. Default to REJECTING if you cannot independently confirm a citation.

Draft (kind: ${d.kind}):
${d.content}

Cited sources:
${JSON.stringify(d.citations)}

Independently check each citation — read the file, view the PR/commit via gh/git, or grep the transcript file directly — and confirm it actually supports the claims made in the draft. Flag ANY claim not clearly supported by a citation you could verify. Be skeptical of dates, causal claims ("this caused that"), and any claim of an alternative having been "considered and rejected" — those are the easiest to fabricate.`,
      { schema: VERIFY_SCHEMA, phase: 'Verify', label: `verify:${d.slug || d.kind}` }
    ).then((v) => ({ ...d, verify: v }))
  )
)

const approved = verified.filter(Boolean).filter((v) => v.verify && v.verify.approved)
const rejected = verified.filter(Boolean).filter((v) => !(v.verify && v.verify.approved))

log(`${approved.length} approved, ${rejected.length} rejected after verification`)

return {
  approved,
  rejected,
  stats: {
    candidates: allCandidates.length,
    novelClustered: (clustered.items || []).length,
    drafts: allDrafts.length,
  },
}

export const meta = {
  name: 'repair-dev-docs-drafts',
  description: 'Revise rejected dev-docs drafts using the verifier feedback that rejected them, then re-verify each revision independently',
  phases: [
    { title: 'Revise' },
    { title: 'Re-verify' },
  ],
}

const REPAIR_SCHEMA = {
  type: 'object',
  properties: {
    kind: { type: 'string', enum: ['adr', 'development', 'troubleshooting', 'skip'] },
    slug: { type: 'string' },
    content: { type: 'string' },
    citations: { type: 'array', items: { type: 'string' } },
  },
  required: ['kind', 'slug', 'content', 'citations'],
}

const VERIFY_SCHEMA = {
  type: 'object',
  properties: {
    approved: { type: 'boolean' },
    issues: { type: 'array', items: { type: 'string' } },
  },
  required: ['approved', 'issues'],
}

phase('Revise')
const revised = await pipeline(
  args,
  (item) =>
    agent(
      `An earlier drafting pass wrote this dev-docs entry for the wakil repo, but an independent adversarial verifier rejected it for specific, cited reasons. Your job is to REVISE it so every remaining claim is independently verifiable, or conclude it should be dropped.

Original draft (kind: ${item.kind}):
${item.content}

Original citations:
${JSON.stringify(item.citations)}

Verifier's rejection reasons (fix every one of these — do not just reword around them, actually re-check the underlying source yourself via Read/Bash/git/gh):
${JSON.stringify(item.verify.issues)}

Instructions:
- Independently re-verify anything you keep — do not trust the original draft's claims, re-derive them.
- Where the verifier found a wrong date/line-number/file-path/name, correct it using the real value (check it yourself).
- Where the verifier found a fabricated or unsupported causal/comparative claim, either find real support for it or delete that specific claim — do not soften the wording while keeping the same unsupported substance.
- Where the verifier found the whole premise stale or reversed (e.g. a bug already fixed elsewhere, a symptom that didn't actually happen as described), rewrite around the ACTUAL, verified situation rather than patching the old framing — if the real story doesn't clear the bar for its target doc (troubleshooting: cost real debugging time, not obvious, plausibly recurs; pattern: generalizes to future work; decision: a real deliberate architectural choice), return kind: "skip".
- If after re-checking you cannot produce a version where every claim is independently verifiable, return kind: "skip" rather than a weaker version.

Return the same shape as before: kind, slug (kebab-case, adr only, else ""), content (full ADR markdown for kind "adr", or just the entry snippet for "development"/"troubleshooting"), citations (exact strings/pointers you can defend).`,
      { schema: REPAIR_SCHEMA, phase: 'Revise', label: `revise:${item.kind}:${item.slug || 'entry'}` }
    )
)

const toVerify = revised.filter(Boolean).filter((d) => d.kind !== 'skip' && d.content)
const skipped = revised.filter(Boolean).filter((d) => d.kind === 'skip' || !d.content)
log(`${toVerify.length} revised, ${skipped.length} dropped as unsalvageable`)

phase('Re-verify')
const verified = await parallel(
  toVerify.map((d) => () =>
    agent(
      `Adversarially verify this REVISED dev-docs draft for the wakil repo against ONLY its cited sources. This is a second pass after an earlier version of this same entry was already rejected once — hold it to the same standard, do not go easier on it. Default to REJECTING if you cannot independently confirm a citation.

Draft (kind: ${d.kind}):
${d.content}

Cited sources:
${JSON.stringify(d.citations)}

Independently check each citation — read the file, view the PR/commit via gh/git, or grep the transcript file directly — and confirm it actually supports the claims made. Flag ANY claim not clearly supported.`,
      { schema: VERIFY_SCHEMA, phase: 'Re-verify', label: `verify:${d.slug || d.kind}` }
    ).then((v) => ({ ...d, verify: v }))
  )
)

const approved = verified.filter(Boolean).filter((v) => v.verify && v.verify.approved)
const stillRejected = verified.filter(Boolean).filter((v) => !(v.verify && v.verify.approved))

log(`${approved.length} approved on repair, ${stillRejected.length} still rejected, ${skipped.length} dropped as unsalvageable`)

return { approved, stillRejected, skipped }

